import logging
import logging.handlers
import os
from uvicorn.logging import DefaultFormatter
from collections import deque

FILE_FORMAT = '%(asctime)s | %(name)-25s | %(levelname)-s | %(message)s'
CONSOLE_FORMAT = '%(levelprefix)-10s %(message)s'

class InMemoryHandler(logging.Handler):
    def __init__(self, max_num_of_logs=500):
        super().__init__()
        self.max_num_of_logs = max_num_of_logs
        self.logs = deque(maxlen=max_num_of_logs)

    def emit(self, record):
        log_entry = self.format(record)
        if not any(log['message'] == log_entry for log in self.logs):
            self.logs.append({'message': log_entry, 'level': record.levelname, 'timestamp': record.created})

    def get_logs(self):
        return list(self.logs)

    def clear_logs(self):
        self.logs.clear()

class ProxyMngrLogger:

    def __init__(self, log_file_name='proxy_mngr.log', log_base_dir=''):
        self.logger = logging.getLogger(__name__)
        self.memory_handler = InMemoryHandler()
        self._configure(log_file_name, log_base_dir)
        self.LOG_METHODS = {
            logging.DEBUG: self.logger.debug,
            logging.INFO: self.logger.info,
            logging.WARNING: self.logger.warning,
            logging.ERROR: self.logger.error,
            logging.CRITICAL: self.logger.critical
        }

    def _configure(self, log_file_name, log_base_dir=''):
        log_dir = os.path.join(log_base_dir, log_file_name)
        self.logger.setLevel(logging.DEBUG)

        console_handler = logging.StreamHandler()
        console_handler.setLevel(logging.INFO)

        # one line is ~200 Bytes, 200 kB should be around 1000 lines
        max_bytes = os.environ.get("MNGR_LOG_MAX_BYTES", 200_000)
        backup_count = os.environ.get("MNGR_LOG_BACKUP_COUNT", 5)
        file_handler = logging.handlers.RotatingFileHandler(log_dir, mode="w", maxBytes=max_bytes, backupCount=backup_count)
        file_handler.setLevel(logging.DEBUG)

        self.memory_handler.setLevel(logging.INFO)
        formatter_file = logging.Formatter(FILE_FORMAT)
        formatter_console = DefaultFormatter(fmt=CONSOLE_FORMAT)

        console_handler.setFormatter(formatter_console)
        file_handler.setFormatter(formatter_file)

        self.logger.addHandler(console_handler)
        self.logger.addHandler(file_handler)
        self.logger.addHandler(self.memory_handler)

    def log(self, message, log_level):
        log_method = self.LOG_METHODS.get(log_level)
        log_method(message)

    def get_logs(self):
        return self.memory_handler.get_logs()

    def clear_memory_logs(self):
        self.memory_handler.clear_logs()
